  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is Physical AI data for national security?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of sensor data and demonstrations that train robots and sensing systems to protect and maintain critical sites such as substations, ports, water plants, and transport hubs, including patrol, inspection, drone detection, and hazardous-area robots."
        }
      },
      {
        "@type": "Question",
        "name": "How is this different from your defense work?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Defense covers military autonomy programs. National security covers civil and homeland programs for infrastructure operators and agencies. Both are limited to protective, non-weapons use."
        }
      },
      {
        "@type": "Question",
        "name": "Who owns the data collected at our site?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "The client does. Storage location, residency, access, and retention are agreed in writing before capture begins."
        }
      },
      {
        "@type": "Question",
        "name": "Can you collect data for small-drone detection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We capture camera and thermal data of cooperative drone flights against varied skies and backgrounds, along with hard negatives such as birds and clutter, following local flight rules."
        }
      },
      {
        "@type": "Question",
        "name": "How do you protect employee and public privacy?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Capture is scoped to what the model needs, and people are blurred or excluded unless the program has a documented reason to keep them."
        }
      },
      {
        "@type": "Question",
        "name": "Can you meet our personnel and site access requirements?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We confirm personnel, escort, and induction requirements during scoping and tell you up front what we can support."
        }
      }
    ]
  }
